import fs from 'node:fs';
import { Session } from 'node:inspector/promises';
import { performance } from 'node:perf_hooks';
import { Markdown } from '../../packages/tui/src/components/markdown.ts';
import { initTheme, getMarkdownTheme } from '../../packages/coding-agent/src/modes/interactive/theme/theme.ts';
initTheme('dark', false);
const kind = process.argv[2] ?? 'table';
const theme = getMarkdownTheme();
let text = kind === 'table' ? '| Key | Description | Value |\n| --- | --- | --- |\n' : kind === 'code' ? '```ts\n' : '';
let row = 0;
while (text.length < 64 * 1024) text += kind === 'table' ? `| field_${row} | **Entry ${row}** with text | ${row++} |\n` : kind === 'code' ? `const value${row} = ${row++}; // typed value\n` : 'ordinary prose words ';
const instance = new Markdown(text, 1, 0, theme, undefined, {incrementalRenderCache: true});
const append = kind === 'table' ? '| next | **Entry** | 42 |\n' : kind === 'code' ? 'const next = 42;\n' : ' prose';
for (let i = 0; i < 40; i++) { text += append; instance.setText(text); instance.render(120); }
const session = new Session(); session.connect();
await session.post('Profiler.enable'); await session.post('Profiler.start');
await session.post('HeapProfiler.startSampling', {samplingInterval:4096, includeObjectsCollectedByMajorGC:true, includeObjectsCollectedByMinorGC:true});
const timings = [];
for (let i = 0; i < 80; i++) { text += append; const start = performance.now(); instance.setText(text); instance.render(120); timings.push(performance.now()-start); }
const {profile:cpu} = await session.post('Profiler.stop');
const {profile:heap} = await session.post('HeapProfiler.stopSampling'); session.disconnect();
const counts = new Map(); for (const id of cpu.samples ?? []) counts.set(id, (counts.get(id) ?? 0) + 1);
const nodes = cpu.nodes.map(n => ({name:n.callFrame.functionName,url:n.callFrame.url,line:n.callFrame.lineNumber+1,samples:counts.get(n.id) ?? 0})).sort((a,b)=>b.samples-a.samples);
const allocations = [], pending=[heap.head]; let bytes=0;
while (pending.length) { const n=pending.pop(); bytes += n.selfSize; if(n.selfSize) allocations.push({name:n.callFrame.functionName,url:n.callFrame.url,line:n.callFrame.lineNumber+1,bytes:n.selfSize}); pending.push(...n.children); }
allocations.sort((a,b)=>b.bytes-a.bytes);
timings.sort((a,b)=>a-b);
const result = {kind,sourceLength:text.length,p50:timings[39],p95:timings[75],profiled:true,bytesPerUpdate:bytes/80,cpu:nodes.slice(0,25),allocations:allocations.slice(0,25)};
fs.writeFileSync(new URL(`probe-${kind}.json`,import.meta.url), JSON.stringify(result,null,2));
console.log(JSON.stringify(result));

