import fs from 'node:fs';
import assert from 'node:assert/strict';
import { registerHooks } from 'node:module';
import { Session } from 'node:inspector/promises';
import { performance } from 'node:perf_hooks';
const [side='candidate',kind='table',sizeArg='65536',mode='timing',label='trial',warmupArg='100'] = process.argv.slice(2);
const size=Number(sizeArg), root=new URL('.',import.meta.url);
const utilsUrl=new URL('../../packages/tui/src/utils.ts',root).href;
const baseline=fs.readFileSync(new URL('utils-baseline.ts',root),'utf8');
registerHooks({load(url,context,nextLoad){
 if(side==='baseline' && url===utilsUrl) return {format:'module-typescript',source:baseline,shortCircuit:true};
 return nextLoad(url,context);
}});
const {Markdown}=await import('../../packages/tui/src/components/markdown.ts');
const {initTheme,getMarkdownTheme}=await import('../../packages/coding-agent/src/modes/interactive/theme/theme.ts');
initTheme('dark',false); const theme=getMarkdownTheme();
let source=kind==='table'?'| Key | Description | Value |\n| --- | --- | --- |\n':kind.startsWith('code')?'```ts\n':'';
let row=0;
function chunk(){
 const index=row++;
 return kind==='table'?`| field_${index} | **Entry ${index}** with text | ${index} |\n`:kind==='code'?`const value${index} = ${index}; // typed value\n`:kind==='code-single'?`value${index} + `:'ordinary prose words ';
}
while(source.length<size) source+=chunk();
const initial=source,states=[];
for(let i=0;i<150;i++){ source+=chunk(); states.push(source); }
function metrics(){ return {incrementalEligibleUpdates:0,incrementalUpdates:0,fullFallbacks:0,sourceCharactersReparsed:0,sourceCharactersRewrapped:0,parserTokensReused:0,parserTokensRebuilt:0,renderedPrefixLinesReused:0,tailLinesRebuilt:0,cachedTokenCount:0,cachedRenderedLines:0,cachedSourceCharacters:0,lastFallbackReason:'none'}; }
let md=new Markdown(initial,1,0,theme,undefined,{incrementalRenderCache:true});
for(let i=0;i<Number(warmupArg);i++){md.setText(states[i%states.length]);md.render(120);}
md.invalidate(); md=undefined;
globalThis.gc();globalThis.gc();
const counters=metrics(); md=new Markdown(initial,1,0,theme,undefined,{incrementalRenderCache:true},counters);md.render(120);
for(const key of Object.keys(counters)) if(typeof counters[key]==='number' && !key.startsWith('cached')) counters[key]=0;
const heapBefore=process.memoryUsage().heapUsed;
let peakHeap=heapBefore,segmentCalls=0,segmentedCharacters=0,inlineCalls=0,tableRows=0,highlightCalls=0;
const originalSegment=Intl.Segmenter.prototype.segment;
if(mode==='counters'){
 Intl.Segmenter.prototype.segment=function(input){segmentCalls++;segmentedCharacters+=input.length;return originalSegment.call(this,input);};
 const inline=Markdown.prototype.renderInlineTokens,table=Markdown.prototype.renderTable,highlight=theme.highlightCode;
 Markdown.prototype.renderInlineTokens=function(...args){inlineCalls++;return inline.apply(this,args);};
 Markdown.prototype.renderTable=function(...args){tableRows+=args[0].rows.length;return table.apply(this,args);};
 theme.highlightCode=function(...args){highlightCalls++;return highlight.apply(this,args);};
}
let session;
if(mode==='allocation'){session=new Session();session.connect();await session.post('HeapProfiler.startSampling',{samplingInterval:4096,includeObjectsCollectedByMajorGC:true,includeObjectsCollectedByMinorGC:true});}
const samples=[];
for(let sample=0;sample<30;sample++){
 const start=performance.now();
 for(let j=0;j<5;j++){md.setText(states[sample*5+j]);md.render(120);}
 samples.push((performance.now()-start)/5);
 peakHeap=Math.max(peakHeap,process.memoryUsage().heapUsed);
}
let sampledBytes=0,top=[];
if(session){const {profile}=await session.post('HeapProfiler.stopSampling');session.disconnect();const pending=[profile.head];while(pending.length){const n=pending.pop();sampledBytes+=n.selfSize;if(n.selfSize)top.push({bytes:n.selfSize,name:n.callFrame.functionName,url:n.callFrame.url,line:n.callFrame.lineNumber+1});pending.push(...n.children);}top.sort((a,b)=>b.bytes-a.bytes);top=top.slice(0,15);}
Intl.Segmenter.prototype.segment=originalSegment;
const finalMetrics={...counters},refs=[];
for(const key of ['cachedLines','incrementalTokenSignatures','incrementalTokenContentLines','incrementalPlainContentLines']) if(md[key]) refs.push(new WeakRef(md[key]));
md.setText('small');md.render(120);md.invalidate();
assert.equal(counters.cachedSourceCharacters,0);assert.equal(counters.cachedRenderedLines,0);assert.equal(counters.cachedTokenCount,0);md=undefined;
await new Promise(setImmediate);globalThis.gc();globalThis.gc();await new Promise(setImmediate);globalThis.gc();
const remaining=refs.reduce((sum,ref)=>sum+(ref.deref()?1:0),0);assert.equal(remaining,0);
const sorted=samples.slice().sort((a,b)=>a-b);
const result={side,kind,size,mode,label,sampleDefinition:'mean of five consecutive setText/render updates',startLength:initial.length,endLength:source.length,samples,p50:sorted[14],p95:sorted[28],sampledBytesPerUpdate:sampledBytes/150,heapBefore,peakHeap,heapAfterGc:process.memoryUsage().heapUsed,finalMetrics,segmentCalls,segmentedCharacters,inlineCalls,tableRows,highlightCalls,releasedArrays:refs.length,remainingArrays:remaining,top};
fs.writeFileSync(new URL(`${label}.json`,root),JSON.stringify(result,null,2));
console.log(JSON.stringify({side,kind,size,mode,p50:result.p50,p95:result.p95,bytes:result.sampledBytesPerUpdate,remaining}));

