import fs from 'node:fs';
import assert from 'node:assert/strict';
import {registerHooks} from 'node:module';
import {performance,PerformanceObserver} from 'node:perf_hooks';
import {setTimeout as delay} from 'node:timers/promises';
const [side,label]=process.argv.slice(2),root=new URL('.',import.meta.url);
const utilsUrl=new URL('../../packages/tui/src/utils.ts',root).href,baseline=fs.readFileSync(new URL('utils-baseline.ts',root),'utf8');
registerHooks({load(url,context,next){return side==='baseline'&&url===utilsUrl?{format:'module-typescript',source:baseline,shortCircuit:true}:next(url,context);}});
const {Markdown}=await import('../../packages/tui/src/components/markdown.ts');
const {initTheme,getMarkdownTheme}=await import('../../packages/coding-agent/src/modes/interactive/theme/theme.ts');
initTheme('dark',false);const theme=getMarkdownTheme();
let base='| Key | Description | Value |\n| --- | --- | --- |\n',row=0;
while(base.length<65536){base+=`| field_${row} | **Entry ${row}** with text | ${row} |\n`;row++;}
const events=[];const observer=new PerformanceObserver(list=>{for(const e of list.getEntries())events.push({kind:e.detail.kind,duration:e.duration});});observer.observe({entryTypes:['gc']});
const cycles=[],refs=[];
for(let cycle=-1;cycle<5;cycle++){
 let md=new Markdown(base,1,0,theme,undefined,{incrementalRenderCache:true}),text=base;md.render(120);
 const before=process.memoryUsage().heapUsed;let peak=before;const durations=[];
 for(let update=0;update<30;update++){
  text+=`| field_${row} | **Entry ${row}** with text | ${row} |\n`;row++;
  const start=performance.now();md.setText(text);md.render(120);const duration=performance.now()-start;durations.push(duration);
  peak=Math.max(peak,process.memoryUsage().heapUsed);await delay(Math.max(0,60-duration));
 }
 for(const key of ['cachedLines','incrementalTokenSignatures','incrementalTokenContentLines'])if(md[key])refs.push(new WeakRef(md[key]));
 md.setText('small');md.invalidate();md=undefined;text=undefined;
 await delay(0);globalThis.gc();globalThis.gc();await delay(0);globalThis.gc();
 if(cycle>=0)cycles.push({before,peak,afterGc:process.memoryUsage().heapUsed,durations});
}
await delay(0);observer.disconnect();const remaining=refs.filter(ref=>ref.deref()).length;assert.equal(remaining,0);
const result={side,intervalMs:60,cycles,gcEvents:events,references:refs.length,remaining};fs.writeFileSync(new URL(`${label}.json`,root),JSON.stringify(result,null,2));console.log(JSON.stringify({side,cycles:cycles.map(c=>({peak:c.peak,afterGc:c.afterGc})),references:refs.length,remaining}));

