import fs from 'node:fs';
import assert from 'node:assert/strict';
import {registerHooks} from 'node:module';
import {performance,PerformanceObserver} from 'node:perf_hooks';
const [side,sizeArg,label,batchArg='50']=process.argv.slice(2),size=Number(sizeArg),batchSize=Number(batchArg),warmupBatches=batchSize>50?10:100,root=new URL('.',import.meta.url);
const utils=new URL('../../packages/tui/src/utils.ts',root).href,baseline=fs.readFileSync(new URL('utils-baseline.ts',root),'utf8');
registerHooks({load(url,context,next){return side==='baseline'&&url===utils?{format:'module-typescript',source:baseline,shortCircuit:true}:next(url,context);}});
const {Markdown}=await import('../../packages/tui/src/components/markdown.ts');
const {initTheme,getMarkdownTheme}=await import('../../packages/coding-agent/src/modes/interactive/theme/theme.ts');
initTheme('dark',false);const initial='ordinary prose words '.repeat(Math.ceil(size/21)),checkpoint=initial+'ordinary prose words ',states=[];let source=checkpoint;
for(let i=0;i<batchSize;i++){source+='ordinary prose words ';states.push(source);}
const metrics={incrementalEligibleUpdates:0,incrementalUpdates:0,fullFallbacks:0,sourceCharactersReparsed:0,sourceCharactersRewrapped:0,parserTokensReused:0,parserTokensRebuilt:0,renderedPrefixLinesReused:0,tailLinesRebuilt:0,cachedTokenCount:0,cachedRenderedLines:0,cachedSourceCharacters:0,lastFallbackReason:'none'};
const md=new Markdown(initial,1,0,getMarkdownTheme(),undefined,{incrementalRenderCache:true},metrics);
const samples=[],gcEvents=[],windows=[];
const observer=new PerformanceObserver(list=>{for(const e of list.getEntries())gcEvents.push({kind:e.detail.kind,start:e.startTime,duration:e.duration});});observer.observe({entryTypes:['gc']});
for(let batch=-warmupBatches;batch<30;batch++){
	md.setText(initial);md.render(120);md.setText(checkpoint);md.render(120);
	const incrementalBefore=metrics.incrementalUpdates;
 const start=performance.now();for(let update=0;update<batchSize;update++){md.setText(states[update]);md.render(120);}
	const end=performance.now();if(batch>=0){samples.push((end-start)/batchSize);windows.push({start,end});}
	assert.equal(metrics.incrementalUpdates-incrementalBefore,batchSize);
}
await new Promise(setImmediate);await new Promise(setImmediate);observer.disconnect();
const sorted=samples.slice().sort((a,b)=>a-b);md.invalidate();assert.equal(metrics.cachedSourceCharacters,0);globalThis.gc();
const result={side,kind:'plain',size,mode:'steady',label,warmup:warmupBatches*batchSize,updates:30*batchSize,batchSize,resetOutsideMeasurement:true,samples,windows,gcEvents,p50:sorted[14],p95:sorted[28],metrics};fs.writeFileSync(new URL(`${label}.json`,root),JSON.stringify(result,null,2));console.log(JSON.stringify({side,size,p50:result.p50,p95:result.p95,incrementalUpdates:metrics.incrementalUpdates}));

