import fs from 'node:fs';
import assert from 'node:assert/strict';
import {registerHooks} from 'node:module';
import {performance} from 'node:perf_hooks';
const [side,mode,label]=process.argv.slice(2),root=new URL('.',import.meta.url),instrument=mode==='counters',configuration=mode.replace('trace-','');
const utils=new URL('../../packages/tui/src/utils.ts',root).href;
let source=fs.readFileSync(side==='baseline'?new URL('utils-baseline.ts',root):new URL(utils),'utf8');
globalThis.pfWidthCalls=0;globalThis.pfSimpleCalls=0;
if(instrument){
 const width='export function visibleWidth(str: string): number {';
 const simple=`function ${side==='baseline'?'terminalAsciiWidth':'terminalSimpleWidth'}(str: string): number {`;
 assert.ok(source.includes(width)&&source.includes(simple));
 source=source.replace(width,width+' globalThis.pfWidthCalls++;').replace(simple,simple+' globalThis.pfSimpleCalls++;');
}
registerHooks({load(url,context,next){return url===utils?{format:'module-typescript',source,shortCircuit:true}:next(url,context);}});
const {Markdown}=await import('../../packages/tui/src/components/markdown.ts');
const {initTheme,getMarkdownTheme}=await import('../../packages/coding-agent/src/modes/interactive/theme/theme.ts');
initTheme('dark',false);const theme=getMarkdownTheme();
const initial='ordinary prose words '.repeat(Math.ceil(16384/21)),states=[];let text=initial;
for(let i=0;i<150;i++){text+='ordinary prose words ';states.push(text);}
function metrics(){return {incrementalEligibleUpdates:0,incrementalUpdates:0,fullFallbacks:0,sourceCharactersReparsed:0,sourceCharactersRewrapped:0,parserTokensReused:0,parserTokensRebuilt:0,renderedPrefixLinesReused:0,tailLinesRebuilt:0,cachedTokenCount:0,cachedRenderedLines:0,cachedSourceCharacters:0,lastFallbackReason:'none'};}
// Compare actual production (no metrics), unchanged metrics shape, and the
// original probe's warmup-to-measurement instrumentation transition.
const warmMetrics=configuration==='uniform'?metrics():undefined;
let md=new Markdown(initial,1,0,theme,undefined,{incrementalRenderCache:true},warmMetrics);
for(let i=0;i<100;i++){md.setText(states[i]);md.render(120);}md.invalidate();md=undefined;globalThis.gc();globalThis.gc();
const measuredMetrics=configuration==='production'?undefined:metrics();
md=new Markdown(initial,1,0,theme,undefined,{incrementalRenderCache:true},measuredMetrics);md.render(120);
globalThis.pfWidthCalls=0;globalThis.pfSimpleCalls=0;
const samples=[];
if(mode.startsWith('trace-'))console.log('DIAGNOSTIC_MEASURE_START');
for(let batch=0;batch<30;batch++){const start=performance.now();for(let j=0;j<5;j++){md.setText(states[batch*5+j]);md.render(120);}samples.push((performance.now()-start)/5);}
if(mode.startsWith('trace-'))console.log('DIAGNOSTIC_MEASURE_END');
const sorted=samples.slice().sort((a,b)=>a-b);const result={side,mode,label,warmup:100,updates:150,samples,p50:sorted[14],p95:sorted[28],visibleWidthCalls:globalThis.pfWidthCalls,changedHelperCalls:globalThis.pfSimpleCalls,metrics:measuredMetrics};
md.invalidate();fs.writeFileSync(new URL(`${label}.json`,root),JSON.stringify(result,null,2));console.log(JSON.stringify(result));

