import fs from 'node:fs';
import assert from 'node:assert/strict';
import {registerHooks} from 'node:module';
const root=new URL('.',import.meta.url),side=process.argv[2];
const baseline=fs.readFileSync(new URL('utils-baseline.ts',root),'utf8');
const utils=new URL('../../packages/tui/src/utils.ts',root).href,dist=new URL('../../packages/tui/dist/utils.js',root).href;
const benchmark=new URL('../../scripts/bench/tui-real-leaf-allocations.ts',root).href;
let table='| Key | Description | Value |\n| --- | --- | --- |\n',row=0;
while(table.length<65536){table+=`| field_${row} | **Entry ${row}** with text | ${row} |\n`;row++;}
registerHooks({load(url,context,next){
 if(side==='baseline'&&(url===utils||url===dist))return {format:'module-typescript',source:url===dist?baseline.replace('"./regex.ts"','"./regex.js"'):baseline,shortCircuit:true};
 if(url===benchmark){
  let source=fs.readFileSync(new URL(url),'utf8');
  const anchor='let growingMarkdown = "";';assert.ok(source.includes(anchor));
  source=source.replace(anchor,`let growingMarkdown = ${JSON.stringify(table)};`);
  const fixture='{ type: "text", text: `plain-${index & 7}` },';assert.ok(source.includes(fixture));
  source=source.replace(fixture,'{ type: "text", text: growingMarkdown += `| next_${index} | **Entry** | 42 |\\n` },');
  return {format:'module-typescript',source,shortCircuit:true};
 }
 return next(url,context);
}});
await import(benchmark);

