 const rows=raw.filter(r=>r.mode==='timing'&&r.label.startsWith(prefix+'control-')&&r.kind===kind&&r.size===size);
 if(rows.length!==4)continue;
 const base=rows.filter(r=>r.side==='baseline'),candidate=rows.filter(r=>r.side==='candidate');
 const meanBase=(base[0].p95+base[1].p95)/2,band=Math.abs(base[0].p95-base[1].p95)/meanBase*100;
 const changes=base.map(b=>{const c=candidate.find(c=>c.label.slice(prefix.length).split('-')[1]===b.label.slice(prefix.length).split('-')[1]);return(c.p95/b.p95-1)*100;});
 groups.push({version:prefix?'final':'initial',kind,size,baseP95:base.map(r=>r.p95),candidateP95:candidate.map(r=>r.p95),baselineBandPercent:band,changesPercent:changes,repeatedRegression:changes.every(n=>n>Math.max(5,band)),unstable:band>10});
}
