for(const side of ['baseline','candidate']){const rows=formal.filter(r=>r.side===side),p95=rows.map(r=>r.p95);summary.formal[side]={processes:rows.length,p50:median(rows.map(r=>r.p50)),p95:median(p95),bandPercent:(Math.max(...p95)-Math.min(...p95))/median(p95)*100,peakHeapMedian:median(rows.map(r=>r.peakHeap)),afterGcMedian:median(rows.map(r=>r.heapAfterGc))};}
summary.improvementPercent=(1-summary.formal.candidate.p95/summary.formal.baseline.p95)*100;
