for(const [prefix,kind,size] of [['steady-v2-','plain',16384],['steady-v2-','plain',65536],['steady-v3-','plain',16384],['steady-v3-','plain',65536],['warm-','code',16384],['warm-','code-single',16384],['final-steady-','plain',16384],['final-steady-','plain',65536]]){
