 const base=rows.filter(r=>r.side==='baseline'),candidate=rows.filter(r=>r.side==='candidate');if(base.length!==5||candidate.length!==5)continue;
 const bp=base.map(r=>r.p95),cp=candidate.map(r=>r.p95);
 summary.followups.push({prefix,kind,size,baselineP95:bp,candidateP95:cp,baselineMedian:median(bp),candidateMedian:median(cp),baselineBandPercent:(Math.max(...bp)-Math.min(...bp))/median(bp)*100,candidateBandPercent:(Math.max(...cp)-Math.min(...cp))/median(cp)*100,changePercent:(median(cp)/median(bp)-1)*100});
}
const manifest=read('resources.json');
