for(const name of ['run.mjs','verify-env.mjs','probe.mjs','measure.mjs','memory.mjs','plain-steady.mjs','plain-diagnostic.mjs','real-table.mjs','final-verification.ps1','collect.mjs']){const text=fs.readFileSync(path.join(root,name),'utf8');reproductionFiles[name]={sha256:sha(text),text};}
const sourceHashes={};for(const name of ['packages/tui/src/utils.ts','packages/tui/dist/utils.js','tests/tui-visible-width.test.ts','tests/tui-complex-markdown.test.ts','scripts/bench/tool-result-presentation-ui-source-audit.ts'])sourceHashes[name]=sha(fs.readFileSync(path.join(repo,name)));
