import { eastAsianWidth } from "get-east-asian-width";
import {
	CJK_BREAK_PATTERN,
	LEADING_NON_PRINTING_PATTERN,
	LINE_BREAK_PATTERN,
	MARK_CHARACTER_PATTERN,
	NON_PRINTING_CHARACTER_PATTERN,
	OSC8_HYPERLINK_PATTERN,
	RGI_EMOJI_PATTERN,
	SGR_PARAMETERS_PATTERN,
	TAB_PATTERN,
	TERMINAL_SPACING_MARK_PATTERN,
	THAI_LAO_AM_PATTERN,
	ZERO_WIDTH_PATTERN,
} from "./regex.ts";

// segmenters (shared instance)
const graphemeSegmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" });
const wordSegmenter = new Intl.Segmenter(undefined, { granularity: "word" });

/**
 * Get the shared grapheme segmenter instance.
 */
export function getGraphemeSegmenter(): Intl.Segmenter {
	return graphemeSegmenter;
}

/**
 * Get the shared word segmenter instance.
 */
export function getWordSegmenter(): Intl.Segmenter {
	return wordSegmenter;
}

/**
 * Check if a grapheme cluster (after segmentation) could possibly be an RGI emoji.
 * This is a fast heuristic to avoid the expensive rgiEmojiRegex test.
 * The tested Unicode blocks are deliberately broad to account for future
 * Unicode additions.
 */
function couldBeEmoji(segment: string): boolean {
	const cp = segment.codePointAt(0)!;
	return (
		(cp >= 0x1f000 && cp <= 0x1fbff) || // Emoji and Pictograph
		(cp >= 0x2300 && cp <= 0x23ff) || // Misc technical
		(cp >= 0x2600 && cp <= 0x27bf) || // Misc symbols, dingbats
		(cp >= 0x2b50 && cp <= 0x2b55) || // Specific stars/circles
		segment.includes("\uFE0F") || // Contains VS16 (emoji presentation selector)
		segment.length > 2 // Multi-codepoint sequences (ZWJ, skin tones, etc.)
	);
}

// One bounded cache shared by full inputs and Unicode cores, never two caches.
const WIDTH_CACHE_SIZE = 512;
const widthCache = new Map<string, number>();

export const cjkBreakRegex = CJK_BREAK_PATTERN;

function isPrintableAscii(str: string): boolean {
	for (let i = 0; i < str.length; i++) {
		const code = str.charCodeAt(i);
		if (code < 0x20 || code > 0x7e) {
			return false;
		}
	}
	return true;
}

function truncateFragmentToWidth(text: string, maxWidth: number): { text: string; width: number } {
	if (maxWidth <= 0 || text.length === 0) {
		return { text: "", width: 0 };
	}

	if (isPrintableAscii(text)) {
		const clipped = text.slice(0, maxWidth);
		return { text: clipped, width: clipped.length };
	}

	const hasAnsi = text.includes("\x1b");
	const hasTabs = text.includes("\t");
	if (!hasAnsi && !hasTabs) {
		let result = "";
		let width = 0;
		for (const { segment } of graphemeSegmenter.segment(text)) {
			const w = graphemeWidth(segment);
			if (width + w > maxWidth) {
				break;
			}
			result += segment;
			width += w;
		}
		return { text: result, width };
	}

	let result = "";
	let width = 0;
	let i = 0;
	let pendingAnsi = "";

	while (i < text.length) {
		const ansi = extractAnsiCode(text, i);
		if (ansi) {
			pendingAnsi += ansi.code;
			i += ansi.length;
			continue;
		}

		if (text[i] === "\t") {
			if (width + 3 > maxWidth) {
				break;
			}
			if (pendingAnsi) {
				result += pendingAnsi;
				pendingAnsi = "";
			}
			result += "\t";
			width += 3;
			i++;
			continue;
		}

		let end = i;
		while (end < text.length && text[end] !== "\t") {
			const nextAnsi = extractAnsiCode(text, end);
			if (nextAnsi) {
				break;
			}
			end++;
		}

		for (const { segment } of graphemeSegmenter.segment(text.slice(i, end))) {
			const w = graphemeWidth(segment);
			if (width + w > maxWidth) {
				return { text: result, width };
			}
			if (pendingAnsi) {
				result += pendingAnsi;
				pendingAnsi = "";
			}
			result += segment;
			width += w;
		}
		i = end;
	}

	return { text: result, width };
}

function finalizeTruncatedResult(
	prefix: string,
	prefixWidth: number,
	ellipsis: string,
	ellipsisWidth: number,
	maxWidth: number,
	pad: boolean,
): string {
	const reset = "\x1b[0m";
	const hyperlinkClose = getActiveOsc8Close(prefix);
	const visibleWidth = prefixWidth + ellipsisWidth;
	let result: string;

	if (ellipsis.length > 0) {
		result = `${prefix}${hyperlinkClose}${reset}${ellipsis}${reset}`;
	} else {
		result = `${prefix}${hyperlinkClose}${reset}`;
	}

	return pad ? result + " ".repeat(Math.max(0, maxWidth - visibleWidth)) : result;
}

/**
 * Calculate the terminal width of a single grapheme cluster.
 * Does not retain segment text in the shared string-width cache. The input is
 * one plain-text cluster, without ANSI sequences; use visibleWidth for strings.
 * Based on code from the string-width library, but includes a possible-emoji
 * check to avoid running the RGI_Emoji regex unnecessarily.
 */
export function graphemeWidth(segment: string): number {
	if (segment === "\t") {
		return 3;
	}

	// Some marks occupy cells even without a base character.
	if (TERMINAL_SPACING_MARK_PATTERN.test(segment)) {
		let length = 0;
		for (const _character of segment) length++;
		return length;
	}

	// Zero-width clusters
	if (ZERO_WIDTH_PATTERN.test(segment)) {
		return 0;
	}

	// Emoji check with pre-filter
	if (couldBeEmoji(segment) && RGI_EMOJI_PATTERN.test(segment)) {
		return 2;
	}

	// Get base visible codepoint
	const base = segment.replace(LEADING_NON_PRINTING_PATTERN, "");
	const cp = base.codePointAt(0);
	if (cp === undefined) {
		return 0;
	}

	// Regional indicator symbols (U+1F1E6..U+1F1FF) are often rendered as
	// full-width emoji in terminals, even when isolated during streaming.
	// Keep width conservative (2) to avoid terminal auto-wrap drift artifacts.
	if (cp >= 0x1f1e6 && cp <= 0x1f1ff) {
		return 2;
	}

	let width = eastAsianWidth(cp);

	// Intl.Segmenter can group multiple terminal-spacing code points into one
	// grapheme. Count trailing visible code points that terminals may allocate
	// cells for: Indic consonants after marks, halfwidth/fullwidth forms, and
	// Thai/Lao AM vowels.
	let followsMark = false;
	let first = true;
	for (const char of base) {
		if (first) {
			first = false;
			continue;
		}
		if (TERMINAL_SPACING_MARK_PATTERN.test(char)) {
			width += 1;
			followsMark = false;
		} else if (MARK_CHARACTER_PATTERN.test(char)) {
			followsMark = true;
		} else if (!NON_PRINTING_CHARACTER_PATTERN.test(char)) {
			const c = char.codePointAt(0)!;
			if (followsMark || (c >= 0xff00 && c <= 0xffef)) {
				// halfwidth + fullwidth forms
				width += eastAsianWidth(c);
			} else if (c === 0x0e33 || c === 0x0eb3) {
				width += 1;
			}
			followsMark = false;
		}
	}

	return width;
}

/** True when every cell in a terminal text run has context-free ASCII width. */
function isSimpleTerminalAsciiRun(text: string, start: number, end: number): boolean {
	for (let index = start; index < end; index++) {
		const codeUnit = text.charCodeAt(index);
		if (codeUnit !== 0x09 && (codeUnit < 0x20 || codeUnit > 0x7e)) return false;
	}
	return true;
}

/**
 * Calculate the visible width of a string in terminal columns.
 */
export function visibleWidth(str: string): number {
	if (str.length === 0) {
		return 0;
	}

	if (isPrintableAscii(str)) return str.length;
	const inputCached = widthCache.get(str);
	if (inputCached !== undefined) return inputCached;

	// ASCII and box-drawing runs can be measured without stripped text or
	// grapheme objects. Fall back as a whole when other Unicode can join across
	// ANSI boundaries, including marks following a box-drawing character.
	const simpleWidth = terminalSimpleWidth(str);
	if (simpleWidth >= 0) {
		rememberWidth(str, simpleWidth);
		return simpleWidth;
	}

	// Normalize: tabs to 3 spaces, strip ANSI escape codes
	let clean = str;
	if (str.includes("\t")) {
		clean = clean.replace(TAB_PATTERN, "   ");
	}
	if (clean.includes("\x1b")) {
		// Strip supported ANSI/OSC/APC escape sequences in one pass.
		// This covers CSI styling/cursor codes, OSC hyperlinks and prompt markers,
		// and APC sequences like CURSOR_MARKER.
		let stripped = "";
		let start = 0;
		for (let i = 0; i < clean.length; i++) {
			const end = findTerminalSequenceEnd(clean, i);
			if (end === 0) continue;
			stripped += clean.slice(start, i);
			start = end;
			i = end - 1;
		}
		clean = stripped + clean.slice(start);
	}

	// Printable ASCII pairs always have a grapheme boundary. Keep one ASCII
	// character at either edge of the Unicode core: a following combining mark
	// or preceding Prepend character can belong to that boundary character.
	// Padding and ordinary ASCII runs need neither segment objects nor regexes.
	let start = 0;
	while (start < clean.length) {
		const code = clean.charCodeAt(start);
		if (code < 0x20 || code > 0x7e) break;
		start++;
	}
	if (start === clean.length) return clean.length;
	let end = clean.length;
	while (end > start) {
		const code = clean.charCodeAt(end - 1);
		if (code < 0x20 || code > 0x7e) break;
		end--;
	}
	if (start > 0) start--;
	if (end < clean.length) end++;
	const asciiColumns = start + clean.length - end;
	const core = clean.slice(start, end);
	// Stripping interrupted ANSI can form a new supported sequence. Such a
	// core's grapheme width differs from its width as raw input; do not alias
	// the two meanings in the shared cache. Tabs have already been normalized.
	const cacheCore = !core.includes("\x1b");
	const cached = cacheCore ? widthCache.get(core) : undefined;
	if (cached !== undefined) {
		const width = asciiColumns + cached;
		rememberWidth(str, width);
		return width;
	}
	let width = 0;
	for (const { segment } of graphemeSegmenter.segment(core)) width += graphemeWidth(segment);
	if (cacheCore) rememberWidth(core, width);
	const result = asciiColumns + width;
	if (!cacheCore || str !== core) rememberWidth(str, result);
	return result;
}

function rememberWidth(text: string, width: number): void {
	if (widthCache.size >= WIDTH_CACHE_SIZE) {
		const firstKey = widthCache.keys().next().value;
		if (firstKey !== undefined) {
			widthCache.delete(firstKey);
		}
	}
	widthCache.set(text, width);
}

/** Exact for ASCII, single-cell box drawing, tabs, and supported terminal sequences. */
function terminalSimpleWidth(str: string): number {
	let width = 0;
	for (let index = 0; index < str.length; index++) {
		const code = str.charCodeAt(index);
		if (code >= 0x20 && code <= 0x7e) {
			width++;
		} else if (code >= 0x2500 && code <= 0x257f) {
			width++;
		} else if (code === 0x09) {
			width += 3;
		} else if (code === 0x1b) {
			const end = findTerminalSequenceEnd(str, index);
			if (end === 0) return -1;
			index = end - 1;
		} else {
			return -1;
		}
	}
	return width;
}

/** Remove ANSI, OSC, and APC control sequences while preserving visible text. */
export function stripTerminalSequences(str: string): string {
	if (!str.includes("\x1b")) return str;
	let result = "";
	let i = 0;
	while (i < str.length) {
		const ansi = extractAnsiCode(str, i);
		if (ansi) {
			i += ansi.length;
			continue;
		}
		result += str[i];
		i++;
	}
	return result;
}

interface GraphemeCellRange {
	start: number;
	end: number;
}

/** Return the terminal-cell range occupied by the grapheme at a visible column. */
export function getGraphemeCellRange(line: string, column: number): GraphemeCellRange | undefined {
	let currentCol = 0;
	let index = 0;
	while (index < line.length) {
		const ansiEnd = findTerminalSequenceEnd(line, index);
		if (ansiEnd !== 0) {
			index = ansiEnd;
			continue;
		}
		let textEnd = index;
		while (textEnd < line.length && findTerminalSequenceEnd(line, textEnd) === 0) textEnd++;
		for (const part of graphemeSegmenter.segment(line.substring(index, textEnd))) {
			const width = graphemeWidth(part.segment);
			if (width > 0 && column >= currentCol && column < currentCol + width) {
				return { start: currentCol, end: currentCol + width };
			}
			currentCol += width;
		}
		index = textEnd;
	}
	return undefined;
}

/** Return one grapheme boundary as a primitive for allocation-sensitive selection paint. */
export function getGraphemeCellStart(line: string, column: number): number | undefined {
	return getGraphemeCellBoundary(line, column, false);
}

/** Return one grapheme boundary as a primitive for allocation-sensitive selection paint. */
export function getGraphemeCellEnd(line: string, column: number): number | undefined {
	return getGraphemeCellBoundary(line, column, true);
}

function getGraphemeCellBoundary(line: string, column: number, endBoundary: boolean): number | undefined {
	let currentCol = 0;
	let i = 0;
	while (i < line.length) {
		const ansiEnd = findTerminalSequenceEnd(line, i);
		if (ansiEnd !== 0) {
			i = ansiEnd;
			continue;
		}
		let textEnd = i;
		while (textEnd < line.length && findTerminalSequenceEnd(line, textEnd) === 0) textEnd++;
		for (const { segment } of graphemeSegmenter.segment(line.slice(i, textEnd))) {
			const width = graphemeWidth(segment);
			if (width > 0 && column >= currentCol && column < currentCol + width) {
				return endBoundary ? currentCol + width : currentCol;
			}
			currentCol += width;
		}
		i = textEnd;
	}
	return undefined;
}

/** Return the OSC 8 hyperlink covering a visible terminal column. */
export function getOsc8LinkAtColumn(line: string, column: number): string | undefined {
	let activeUrl: string | undefined;
	let currentCol = 0;
	let i = 0;
	while (i < line.length) {
		const ansi = extractAnsiCode(line, i);
		if (ansi) {
			const hyperlink = OSC8_HYPERLINK_PATTERN.exec(ansi.code);
			if (hyperlink) activeUrl = hyperlink[1] || undefined;
			i += ansi.length;
			continue;
		}
		let textEnd = i;
		while (textEnd < line.length && !extractAnsiCode(line, textEnd)) textEnd++;
		for (const { segment } of graphemeSegmenter.segment(line.slice(i, textEnd))) {
			const width = segment === "\t" ? 3 : graphemeWidth(segment);
			if (column >= currentCol && column < currentCol + width) return activeUrl;
			currentCol += width;
		}
		i = textEnd;
	}
	return undefined;
}

/**
 * Normalize text for terminal output without changing logical editor content.
 * Some terminals render precomposed Thai/Lao AM vowels inconsistently during
 * differential repaint. Their compatibility decompositions have the same cell
 * width but avoid stale-cell artifacts in terminal renderers. Visible tabs are
 * expanded to the fixed width used by layout so terminal tab stops cannot wrap
 * a logical line, while tabs inside terminal string sequences stay untouched.
 */
export function normalizeTerminalOutput(str: string): string {
	let normalized = str;
	if (THAI_LAO_AM_PATTERN.test(normalized)) {
		let decomposed = "";
		let segmentStart = 0;
		for (let index = 0; index < normalized.length; index++) {
			const character = normalized[index];
			if (character !== "\u0e33" && character !== "\u0eb3") continue;
			decomposed += normalized.slice(segmentStart, index);
			decomposed += character === "\u0e33" ? "\u0e4d\u0e32" : "\u0ecd\u0eb2";
			segmentStart = index + 1;
		}
		normalized = decomposed + normalized.slice(segmentStart);
	}
	if (!normalized.includes("\t")) return normalized;

	let result = "";
	let i = 0;
	while (i < normalized.length) {
		const ansi = extractAnsiCode(normalized, i);
		if (ansi) {
			result += ansi.code;
			i += ansi.length;
			continue;
		}
		result += normalized[i] === "\t" ? "   " : normalized[i];
		i++;
	}
	return result;
}

/**
 * Extract ANSI escape sequences from a string at the given position.
 */
export function extractAnsiCode(str: string, pos: number): { code: string; length: number } | null {
	const end = findTerminalSequenceEnd(str, pos);
	return end === 0 ? null : { code: str.substring(pos, end), length: end - pos };
}

/** Return the exclusive end of a supported terminal sequence without allocating a result wrapper. */
function findTerminalSequenceEnd(str: string, pos: number): number {
	if (pos >= str.length || str[pos] !== "\x1b") return 0;
	const next = str[pos + 1];
	if (next === "[") {
		let index = pos + 2;
		while (index < str.length) {
			const code = str.charCodeAt(index);
			if (code >= 0x40 && code <= 0x7e) return index + 1;
			// CSI parameters/intermediates only. An interrupted sequence must not
			// scan across another ESC and rescan the same suffix at every position.
			if (code < 0x20 || code > 0x3f) return 0;
			index++;
		}
		return 0;
	}
	if (next === "]" || next === "_") {
		let index = pos + 2;
		while (index < str.length) {
			if (str[index] === "\x07") return index + 1;
			if (str[index] === "\x1b") return str[index + 1] === "\\" ? index + 2 : 0;
			index++;
		}
	}
	return 0;
}

type Osc8Terminator = "\x07" | "\x1b\\";

interface ActiveHyperlink {
	params: string;
	url: string;
	terminator: Osc8Terminator;
}

function parseOsc8Hyperlink(ansiCode: string): ActiveHyperlink | null | undefined {
	if (!ansiCode.startsWith("\x1b]8;")) {
		return undefined;
	}

	const terminator: Osc8Terminator = ansiCode.endsWith("\x07") ? "\x07" : "\x1b\\";
	const body = ansiCode.slice(4, terminator === "\x07" ? -1 : -2);
	const separatorIndex = body.indexOf(";");
	if (separatorIndex === -1) {
		return undefined;
	}

	const params = body.slice(0, separatorIndex);
	const url = body.slice(separatorIndex + 1);
	if (!url) {
		return null;
	}
	return { params, url, terminator };
}

function formatOsc8Hyperlink(hyperlink: ActiveHyperlink): string {
	return `\x1b]8;${hyperlink.params};${hyperlink.url}${hyperlink.terminator}`;
}

function formatOsc8Close(terminator: Osc8Terminator): string {
	return `\x1b]8;;${terminator}`;
}

function getActiveOsc8Close(prefix: string): string {
	if (!prefix.includes("\x1b]8;")) {
		return "";
	}

	let activeHyperlink: ActiveHyperlink | null = null;
	let i = 0;
	while (i < prefix.length) {
		const ansi = extractAnsiCode(prefix, i);
		if (ansi) {
			const hyperlink = parseOsc8Hyperlink(ansi.code);
			if (hyperlink !== undefined) {
				activeHyperlink = hyperlink;
			}
			i += ansi.length;
		} else {
			i++;
		}
	}
	return activeHyperlink ? formatOsc8Close(activeHyperlink.terminator) : "";
}

/**
 * Track active ANSI SGR codes to preserve styling across line breaks.
 */
class AnsiCodeTracker {
	// Track individual attributes separately so we can reset them specifically
	private bold = false;
	private dim = false;
	private italic = false;
	private underline = false;
	private blink = false;
	private inverse = false;
	private hidden = false;
	private strikethrough = false;
	private fgColor: string | null = null; // Stores the full code like "31" or "38;5;240"
	private bgColor: string | null = null; // Stores the full code like "41" or "48;5;240"
	private activeHyperlink: ActiveHyperlink | null = null;

	process(ansiCode: string): void {
		// OSC 8 hyperlink: \x1b]8;;<url>\x1b\\ (open) or \x1b]8;;\x1b\\ (close).
		// Preserve the original terminator because some terminals only make BEL-terminated
		// links clickable. OAuth login URLs use BEL, so reopening wrapped lines with ST
		// made only the first physical line clickable in those terminals.
		const hyperlink = parseOsc8Hyperlink(ansiCode);
		if (hyperlink !== undefined) {
			this.activeHyperlink = hyperlink;
			return;
		}

		if (!ansiCode.endsWith("m")) {
			return;
		}

		// Extract the parameters between \x1b[ and m
		const match = ansiCode.match(SGR_PARAMETERS_PATTERN);
		if (!match) return;

		const params = match[1];
		if (params === "" || params === "0") {
			// Full reset
			this.reset();
			return;
		}

		// Parse parameters (can be semicolon-separated)
		const parts = params.split(";");
		let i = 0;
		while (i < parts.length) {
			const code = Number.parseInt(parts[i], 10);

			// Handle 256-color and RGB codes which consume multiple parameters
			if (code === 38 || code === 48) {
				// 38;5;N (256 color fg) or 38;2;R;G;B (RGB fg)
				// 48;5;N (256 color bg) or 48;2;R;G;B (RGB bg)
				if (parts[i + 1] === "5" && parts[i + 2] !== undefined) {
					// 256 color: 38;5;N or 48;5;N
					const colorCode = `${parts[i]};${parts[i + 1]};${parts[i + 2]}`;
					if (code === 38) {
						this.fgColor = colorCode;
					} else {
						this.bgColor = colorCode;
					}
					i += 3;
					continue;
				} else if (parts[i + 1] === "2" && parts[i + 4] !== undefined) {
					// RGB color: 38;2;R;G;B or 48;2;R;G;B
					const colorCode = `${parts[i]};${parts[i + 1]};${parts[i + 2]};${parts[i + 3]};${parts[i + 4]}`;
					if (code === 38) {
						this.fgColor = colorCode;
					} else {
						this.bgColor = colorCode;
					}
					i += 5;
					continue;
				}
			}

			// Standard SGR codes
			switch (code) {
				case 0:
					this.reset();
					break;
				case 1:
					this.bold = true;
					break;
				case 2:
					this.dim = true;
					break;
				case 3:
					this.italic = true;
					break;
				case 4:
					this.underline = true;
					break;
				case 5:
					this.blink = true;
					break;
				case 7:
					this.inverse = true;
					break;
				case 8:
					this.hidden = true;
					break;
				case 9:
					this.strikethrough = true;
					break;
				case 21:
					this.bold = false;
					break; // Some terminals
				case 22:
					this.bold = false;
					this.dim = false;
					break;
				case 23:
					this.italic = false;
					break;
				case 24:
					this.underline = false;
					break;
				case 25:
					this.blink = false;
					break;
				case 27:
					this.inverse = false;
					break;
				case 28:
					this.hidden = false;
					break;
				case 29:
					this.strikethrough = false;
					break;
				case 39:
					this.fgColor = null;
					break; // Default fg
				case 49:
					this.bgColor = null;
					break; // Default bg
				default:
					// Standard foreground colors 30-37, 90-97
					if ((code >= 30 && code <= 37) || (code >= 90 && code <= 97)) {
						this.fgColor = String(code);
					}
					// Standard background colors 40-47, 100-107
					else if ((code >= 40 && code <= 47) || (code >= 100 && code <= 107)) {
						this.bgColor = String(code);
					}
					break;
			}
			i++;
		}
	}

	private reset(): void {
		this.bold = false;
		this.dim = false;
		this.italic = false;
		this.underline = false;
		this.blink = false;
		this.inverse = false;
		this.hidden = false;
		this.strikethrough = false;
		this.fgColor = null;
		this.bgColor = null;
		// SGR reset does not affect OSC 8 hyperlink state
	}

	/** Clear all state for reuse. */
	clear(): void {
		this.reset();
		this.activeHyperlink = null;
	}

	getActiveCodes(): string {
		const codes: string[] = [];
		if (this.bold) codes.push("1");
		if (this.dim) codes.push("2");
		if (this.italic) codes.push("3");
		if (this.underline) codes.push("4");
		if (this.blink) codes.push("5");
		if (this.inverse) codes.push("7");
		if (this.hidden) codes.push("8");
		if (this.strikethrough) codes.push("9");
		if (this.fgColor) codes.push(this.fgColor);
		if (this.bgColor) codes.push(this.bgColor);

		let result = codes.length > 0 ? `\x1b[${codes.join(";")}m` : "";
		if (this.activeHyperlink) {
			result += formatOsc8Hyperlink(this.activeHyperlink);
		}
		return result;
	}

	hasActiveCodes(): boolean {
		return (
			this.bold ||
			this.dim ||
			this.italic ||
			this.underline ||
			this.blink ||
			this.inverse ||
			this.hidden ||
			this.strikethrough ||
			this.fgColor !== null ||
			this.bgColor !== null ||
			this.activeHyperlink !== null
		);
	}

	/**
	 * Get reset codes for attributes that need to be turned off at line end.
	 * Underline must be closed to prevent bleeding into padding.
	 * Active OSC 8 hyperlinks must be closed and re-opened on the next line.
	 * Returns empty string if no attributes need closing.
	 */
	getLineEndReset(): string {
		let result = "";
		if (this.underline) {
			result += "\x1b[24m"; // Underline off only
		}
		if (this.activeHyperlink) {
			result += formatOsc8Close(this.activeHyperlink.terminator); // Re-opened at line start via getActiveCodes()
		}
		return result;
	}
}

function updateTrackerFromText(text: string, tracker: AnsiCodeTracker): void {
	let i = 0;
	while (i < text.length) {
		const ansiResult = extractAnsiCode(text, i);
		if (ansiResult) {
			tracker.process(ansiResult.code);
			i += ansiResult.length;
		} else {
			i++;
		}
	}
}

/**
 * Split text into words while keeping ANSI codes attached.
 */
function splitIntoTokensWithAnsi(text: string): string[] {
	const tokens: string[] = [];
	let current = "";
	let pendingAnsi = ""; // ANSI codes waiting to be attached to next visible content
	let currentKind: "space" | "word" | null = null;
	let i = 0;

	while (i < text.length) {
		const ansiEnd = findTerminalSequenceEnd(text, i);
		if (ansiEnd) {
			// Hold ANSI codes separately - they'll be attached to the next visible char
			pendingAnsi += text.slice(i, ansiEnd);
			i = ansiEnd;
			continue;
		}

		let end = i;
		while (end < text.length && !findTerminalSequenceEnd(text, end)) {
			end++;
		}

		const portion = text.slice(i, end);
		// Only take this path for a complete ASCII run: a following Unicode mark
		// can combine with its ASCII base, so mixed runs still use the segmenter.
		if (isPrintableAscii(portion)) {
			while (i < end) {
				const kind = text.charCodeAt(i) === 0x20 ? "space" : "word";
				let next = i + 1;
				while (next < end && (text.charCodeAt(next) === 0x20) === (kind === "space")) next++;
				if (current && currentKind !== kind) {
					tokens.push(current);
					current = "";
				}
				current += pendingAnsi + text.slice(i, next);
				pendingAnsi = "";
				currentKind = kind;
				i = next;
			}
			continue;
		}
		for (const { segment } of graphemeSegmenter.segment(portion)) {
			const segmentIsSpace = segment === " ";
			if (!segmentIsSpace && cjkBreakRegex.test(segment)) {
				if (current) {
					tokens.push(current);
					current = "";
					currentKind = null;
				}
				const token = pendingAnsi + segment;
				pendingAnsi = "";
				tokens.push(token);
				continue;
			}

			const segmentKind = segmentIsSpace ? "space" : "word";
			if (current && currentKind !== segmentKind) {
				tokens.push(current);
				current = "";
				currentKind = null;
			}

			// Attach any pending ANSI codes to this visible character
			if (pendingAnsi) {
				current += pendingAnsi;
				pendingAnsi = "";
			}

			currentKind = segmentKind;
			current += segment;
		}

		i = end;
	}

	// Handle any remaining pending ANSI codes (attach to last token)
	if (pendingAnsi) {
		if (current) {
			current += pendingAnsi;
		} else if (tokens.length > 0) {
			tokens[tokens.length - 1] += pendingAnsi;
		} else {
			current = pendingAnsi;
		}
	}

	if (current) {
		tokens.push(current);
	}

	return tokens;
}

/**
 * Wrap text with ANSI codes preserved.
 *
 * ONLY does word wrapping - NO padding, NO background colors.
 * Returns lines where each line is <= width visible chars.
 * Active ANSI codes are preserved across line breaks.
 *
 * @param text - Text to wrap (may contain ANSI codes and newlines)
 * @param width - Maximum visible width per line
 * @returns Array of wrapped lines (NOT padded to width)
 */
export function wrapTextWithAnsi(text: string, width: number): string[] {
	if (!text) {
		return [""];
	}

	// Handle newlines by processing each line separately
	// Track ANSI state across lines so styles carry over after literal newlines
	const inputLines = text.split(LINE_BREAK_PATTERN);
	const result: string[] = [];
	const tracker = new AnsiCodeTracker();

	for (const inputLine of inputLines) {
		// Prepend active ANSI codes from previous lines (except for first line)
		const prefix = result.length > 0 ? tracker.getActiveCodes() : "";
		const wrappedLines = wrapSingleLine(prefix + inputLine, width);
		for (const wrappedLine of wrappedLines) {
			result.push(wrappedLine);
		}
		// Update tracker with codes from this line for next iteration
		updateTrackerFromText(inputLine, tracker);
	}

	return result.length > 0 ? result : [""];
}

/** Call-owned bounded collector; returned arrays are never reused as scratch. */
class VisualTail {
	readonly lines: string[] = [];
	count = 0;
	private readonly limit: number;
	constructor(limit: number) { this.limit = limit; }
	push(line: string): void {
		if (this.limit > 0) this.lines[this.count % this.limit] = line;
		this.count++;
	}
	finish(): { lines: string[]; skippedCount: number } {
		const output: string[] = [];
		const start = Math.max(0, this.count - this.limit);
		for (let index = start; index < this.count; index++) output.push(this.lines[index % this.limit]);
		this.lines.length = 0;
		return { lines: output, skippedCount: start };
	}
}

/** Same ANSI/Unicode layout as wrapTextWithAnsi, retaining only the visual tail. */
export function wrapTextWithAnsiTail(text: string, width: number, limit: number): { lines: string[]; skippedCount: number } {
	const tail = new VisualTail(Math.max(0, Math.floor(limit)));
	const tracker = new AnsiCodeTracker();
	let start = 0;
	while (start <= text.length) {
		let end = start;
		while (end < text.length && text.charCodeAt(end) !== 10 && text.charCodeAt(end) !== 13) end++;
		const input = text.slice(start, end);
		wrapSingleLine((tail.count ? tracker.getActiveCodes() : "") + input, Math.max(1, width), tail);
		updateTrackerFromText(input, tracker);
		if (end === text.length) break;
		start = end + (text[end] === "\r" && text[end + 1] === "\n" ? 2 : 1);
	}
	return tail.finish();
}

function wrapSingleLine(line: string, width: number, tail?: VisualTail): string[] {
	if (!line) {
		if (tail) { tail.push(""); return tail.lines; }
		return [""];
	}

	const visibleLength = visibleWidth(line);
	if (visibleLength <= width) {
		if (tail) { tail.push(line); return tail.lines; }
		return [line];
	}

	const wrapped: string[] = [];
	const tracker = new AnsiCodeTracker();
	const tokens = splitIntoTokensWithAnsi(line);

	let currentLine = "";
	let currentVisibleLength = 0;

	for (const token of tokens) {
		const tokenVisibleLength = visibleWidth(token);
		const isWhitespace = token.trim() === "";

		// Token itself is too long - break it character by character
		if (tokenVisibleLength > width && !isWhitespace) {
			if (currentLine) {
				// Add specific reset for underline only (preserves background)
				const lineEndReset = tracker.getLineEndReset();
				if (lineEndReset) {
					currentLine += lineEndReset;
				}
				if (tail) tail.push(currentLine.trimEnd()); else wrapped.push(currentLine);
				currentLine = "";
				currentVisibleLength = 0;
			}

			// Break long token - breakLongWord handles its own resets
			const broken = breakLongWord(token, width, tracker, tail);
			for (let i = 0; i < broken.length - 1; i++) {
				wrapped.push(broken[i]!);
			}
			currentLine = broken[broken.length - 1];
			currentVisibleLength = visibleWidth(currentLine);
			continue;
		}

		// Check if adding this token would exceed width
		const totalNeeded = currentVisibleLength + tokenVisibleLength;

		if (totalNeeded > width && currentVisibleLength > 0) {
			// Trim trailing whitespace, then add underline reset (not full reset, to preserve background)
			let lineToWrap = currentLine.trimEnd();
			const lineEndReset = tracker.getLineEndReset();
			if (lineEndReset) {
				lineToWrap += lineEndReset;
			}
			if (tail) tail.push(lineToWrap.trimEnd()); else wrapped.push(lineToWrap);
			if (isWhitespace) {
				// Don't start new line with whitespace
				currentLine = tracker.getActiveCodes();
				currentVisibleLength = 0;
			} else {
				currentLine = tracker.getActiveCodes() + token;
				currentVisibleLength = tokenVisibleLength;
			}
		} else {
			// Add to current line
			currentLine += token;
			currentVisibleLength += tokenVisibleLength;
		}

		updateTrackerFromText(token, tracker);
	}

	if (currentLine) {
		// No reset at end of final line - let caller handle it
		if (tail) tail.push(currentLine.trimEnd()); else wrapped.push(currentLine);
	}

	// Trailing whitespace can cause lines to exceed the requested width
	if (tail) return tail.lines;
	if (wrapped.length === 0) return [""];
	for (let index = 0; index < wrapped.length; index++) wrapped[index] = wrapped[index]!.trimEnd();
	return wrapped;
}

const PUNCTUATION_CHARACTERS = "(){}[]<>.,;:'\"!?+-=*/\\|&%^$#@~`";

/**
 * Check if a character is whitespace.
 */
export function isWhitespaceChar(char: string): boolean {
	for (let index = 0; index < char.length; index++) {
		const code = char.charCodeAt(index);
		if (
			(code >= 0x09 && code <= 0x0d) ||
			code === 0x20 ||
			code === 0xa0 ||
			code === 0x1680 ||
			(code >= 0x2000 && code <= 0x200a) ||
			code === 0x2028 ||
			code === 0x2029 ||
			code === 0x202f ||
			code === 0x205f ||
			code === 0x3000 ||
			code === 0xfeff
		) {
			return true;
		}
	}
	return false;
}

/**
 * Check if a character is punctuation.
 */
export function isPunctuationChar(char: string): boolean {
	return char.length === 1 && PUNCTUATION_CHARACTERS.includes(char);
}

function breakLongWord(word: string, width: number, tracker: AnsiCodeTracker, tail?: VisualTail): string[] {
	const lines: string[] = [];
	let currentLine = tracker.getActiveCodes();
	let currentWidth = 0;

	// Consume each run directly. Do not retain a per-grapheme record array,
	// especially when the caller only wants a bounded visual tail.
	let i = 0;
	while (i < word.length) {
		const ansiEnd = findTerminalSequenceEnd(word, i);
		if (ansiEnd) {
			const code = word.slice(i, ansiEnd);
			currentLine += code;
			tracker.process(code);
			i = ansiEnd;
			continue;
		}
		let end = i;
		while (end < word.length && !findTerminalSequenceEnd(word, end)) end++;
		const portion = word.slice(i, end);
		if (isPrintableAscii(portion) && Number.isSafeInteger(width) && width > 0) {
			while (i < end) {
				if (currentWidth >= width) {
					currentLine += tracker.getLineEndReset();
					if (tail) tail.push(currentLine.trimEnd()); else lines.push(currentLine);
					currentLine = tracker.getActiveCodes();
					currentWidth = 0;
				}
				const next = Math.min(end, i + width - currentWidth);
				currentLine += word.slice(i, next);
				currentWidth += next - i;
				i = next;
			}
			continue;
		}
		for (const { segment } of graphemeSegmenter.segment(portion)) {
			if (!segment) continue;
			const segmentWidth = visibleWidth(segment);
			if (currentWidth + segmentWidth > width) {
				currentLine += tracker.getLineEndReset();
				if (tail) tail.push(currentLine.trimEnd()); else lines.push(currentLine);
				currentLine = tracker.getActiveCodes();
				currentWidth = 0;
			}
			currentLine += segment;
			currentWidth += segmentWidth;
		}
		i = end;
	}

	if (currentLine) {
		// No reset at end of final segment - caller handles continuation
		lines.push(currentLine);
	}

	return lines.length > 0 ? lines : [""];
}

/**
 * Apply background color to a line, padding to full width.
 *
 * @param line - Line of text (may contain ANSI codes)
 * @param width - Total width to pad to
 * @param bgFn - Background color function
 * @returns Line with background applied and padded to width
 */
export function applyBackgroundToLine(line: string, width: number, bgFn: (text: string) => string): string {
	// Calculate padding needed
	const visibleLen = visibleWidth(line);
	const paddingNeeded = Math.max(0, width - visibleLen);
	const padding = " ".repeat(paddingNeeded);

	// Apply background to content + padding
	const withPadding = line + padding;
	return bgFn(withPadding);
}

/**
 * Truncate text to fit within a maximum visible width, adding ellipsis if needed.
 * Optionally pad with spaces to reach exactly maxWidth.
 * Properly handles ANSI escape codes (they don't count toward width).
 *
 * @param text - Text to truncate (may contain ANSI codes)
 * @param maxWidth - Maximum visible width
 * @param ellipsis - Ellipsis string to append when truncating (default: "...")
 * @param pad - If true, pad result with spaces to exactly maxWidth (default: false)
 * @returns Truncated text, optionally padded to exactly maxWidth
 */
export function truncateToWidth(
	text: string,
	maxWidth: number,
	ellipsis: string = "...",
	pad: boolean = false,
): string {
	if (maxWidth <= 0) {
		return "";
	}

	if (text.length === 0) {
		return pad ? " ".repeat(maxWidth) : "";
	}

	const ellipsisWidth = visibleWidth(ellipsis);
	if (ellipsisWidth >= maxWidth) {
		const textWidth = visibleWidth(text);
		if (textWidth <= maxWidth) {
			return pad ? text + " ".repeat(maxWidth - textWidth) : text;
		}

		const clippedEllipsis = truncateFragmentToWidth(ellipsis, maxWidth);
		if (clippedEllipsis.width === 0) {
			return pad ? " ".repeat(maxWidth) : "";
		}
		return finalizeTruncatedResult("", 0, clippedEllipsis.text, clippedEllipsis.width, maxWidth, pad);
	}

	if (isPrintableAscii(text)) {
		if (text.length <= maxWidth) {
			return pad ? text + " ".repeat(maxWidth - text.length) : text;
		}
		const targetWidth = maxWidth - ellipsisWidth;
		return finalizeTruncatedResult(text.slice(0, targetWidth), targetWidth, ellipsis, ellipsisWidth, maxWidth, pad);
	}

	const targetWidth = maxWidth - ellipsisWidth;
	let result = "";
	let pendingAnsi = "";
	let visibleSoFar = 0;
	let keptWidth = 0;
	let keepContiguousPrefix = true;
	let overflowed = false;
	let exhaustedInput = false;
	const hasAnsi = text.includes("\x1b");
	const hasTabs = text.includes("\t");

	if (!hasAnsi && !hasTabs) {
		for (const { segment } of graphemeSegmenter.segment(text)) {
			const width = graphemeWidth(segment);
			if (keepContiguousPrefix && keptWidth + width <= targetWidth) {
				result += segment;
				keptWidth += width;
			} else {
				keepContiguousPrefix = false;
			}
			visibleSoFar += width;
			if (visibleSoFar > maxWidth) {
				overflowed = true;
				break;
			}
		}
		exhaustedInput = !overflowed;
	} else {
		let i = 0;
		while (i < text.length) {
			const ansi = extractAnsiCode(text, i);
			if (ansi) {
				pendingAnsi += ansi.code;
				i += ansi.length;
				continue;
			}

			if (text[i] === "\t") {
				if (keepContiguousPrefix && keptWidth + 3 <= targetWidth) {
					if (pendingAnsi) {
						result += pendingAnsi;
						pendingAnsi = "";
					}
					result += "\t";
					keptWidth += 3;
				} else {
					keepContiguousPrefix = false;
					pendingAnsi = "";
				}
				visibleSoFar += 3;
				if (visibleSoFar > maxWidth) {
					overflowed = true;
					break;
				}
				i++;
				continue;
			}

			let end = i;
			while (end < text.length && text[end] !== "\t") {
				const nextAnsi = extractAnsiCode(text, end);
				if (nextAnsi) {
					break;
				}
				end++;
			}

			for (const { segment } of graphemeSegmenter.segment(text.slice(i, end))) {
				const width = graphemeWidth(segment);
				if (keepContiguousPrefix && keptWidth + width <= targetWidth) {
					if (pendingAnsi) {
						result += pendingAnsi;
						pendingAnsi = "";
					}
					result += segment;
					keptWidth += width;
				} else {
					keepContiguousPrefix = false;
					pendingAnsi = "";
				}

				visibleSoFar += width;
				if (visibleSoFar > maxWidth) {
					overflowed = true;
					break;
				}
			}
			if (overflowed) {
				break;
			}
			i = end;
		}
		exhaustedInput = i >= text.length;
	}

	if (!overflowed && exhaustedInput) {
		return pad ? text + " ".repeat(Math.max(0, maxWidth - visibleSoFar)) : text;
	}

	return finalizeTruncatedResult(result, keptWidth, ellipsis, ellipsisWidth, maxWidth, pad);
}

/**
 * Extract a range of visible columns from a line. Handles ANSI codes and wide chars.
 * @param strict - If true, exclude wide chars at boundary that would extend past the range
 */
export function sliceByColumn(line: string, startCol: number, length: number, strict = false): string {
	return sliceColumns(line, startCol, length, strict);
}

export interface SliceWithWidthResult {
	text: string;
	width: number;
}

/** Like sliceByColumn but also returns the actual visible width of the result. */
export function sliceWithWidth(
	line: string,
	startCol: number,
	length: number,
	strict = false,
): SliceWithWidthResult {
	const result: SliceWithWidthResult = { text: "", width: 0 };
	result.text = sliceColumns(line, startCol, length, strict, result);
	return result;
}

/** Fill caller-owned scratch for hot paths that need both text and width. */
export function sliceWithWidthInto(
	line: string,
	startCol: number,
	length: number,
	strict: boolean,
	result: SliceWithWidthResult,
): void {
	result.text = sliceColumns(line, startCol, length, strict, result);
}

function sliceColumns(
	line: string,
	startCol: number,
	length: number,
	strict: boolean,
	widthResult?: SliceWithWidthResult,
): string {
	if (length <= 0) {
		if (widthResult) widthResult.width = 0;
		return "";
	}
	const endCol = startCol + length;
	let result = "",
		resultWidth = 0,
		currentCol = 0,
		i = 0,
		pendingAnsi = "";

	while (i < line.length) {
		const ansiEnd = findTerminalSequenceEnd(line, i);
		if (ansiEnd !== 0) {
			const code = line.substring(i, ansiEnd);
			if (currentCol >= startCol && currentCol < endCol) {
				// Codes inherited from before the slice precede boundary resets/styles.
				if (pendingAnsi) {
					result += pendingAnsi;
					pendingAnsi = "";
				}
				result += code;
			} else if (currentCol < startCol) pendingAnsi += code;
			i = ansiEnd;
			continue;
		}

		let textEnd = i;
		while (textEnd < line.length && findTerminalSequenceEnd(line, textEnd) === 0) textEnd++;

		if (isSimpleTerminalAsciiRun(line, i, textEnd)) {
			for (let textIndex = i; textIndex < textEnd; textIndex++) {
				const width = line.charCodeAt(textIndex) === 0x09 ? 3 : 1;
				const inRange = currentCol >= startCol && currentCol < endCol;
				const fits = !strict || currentCol + width <= endCol;
				if (inRange && fits) {
					if (pendingAnsi) {
						result += pendingAnsi;
						pendingAnsi = "";
					}
					result += line[textIndex];
					resultWidth += width;
				}
				currentCol += width;
				if (currentCol >= endCol) break;
			}
		} else {
			for (const part of graphemeSegmenter.segment(line.substring(i, textEnd))) {
				const segment = part.segment;
				const width = graphemeWidth(segment);
				const inRange = currentCol >= startCol && currentCol < endCol;
				const fits = !strict || currentCol + width <= endCol;
				if (inRange && fits) {
					if (pendingAnsi) {
						result += pendingAnsi;
						pendingAnsi = "";
					}
					result += segment;
					resultWidth += width;
				}
				currentCol += width;
				if (currentCol >= endCol) break;
			}
		}
		i = textEnd;
		if (currentCol >= endCol) break;
	}
	if (widthResult) widthResult.width = resultWidth;
	return result;
}

// Pooled tracker instance for extractSegments (avoids allocation per call)
const pooledStyleTracker = new AnsiCodeTracker();

/**
 * Extract "before" and "after" segments from a line in a single pass.
 * Used for overlay compositing where we need content before and after the overlay region.
 * Preserves styling from before the overlay that should affect content after it.
 */
export function extractSegments(
	line: string,
	beforeEnd: number,
	afterStart: number,
	afterLen: number,
	strictAfter = false,
): ExtractedSegmentsResult {
	const result: ExtractedSegmentsResult = { before: "", beforeWidth: 0, after: "", afterWidth: 0 };
	extractSegmentsInto(line, beforeEnd, afterStart, afterLen, strictAfter, result);
	return result;
}

export interface ExtractedSegmentsResult {
	before: string;
	beforeWidth: number;
	after: string;
	afterWidth: number;
}

/** Fill caller-owned segment scratch for synchronous overlay composition. */
export function extractSegmentsInto(
	line: string,
	beforeEnd: number,
	afterStart: number,
	afterLen: number,
	strictAfter: boolean,
	result: ExtractedSegmentsResult,
): void {
	let before = "",
		beforeWidth = 0,
		after = "",
		afterWidth = 0;
	let currentCol = 0,
		i = 0;
	let pendingAnsiBefore = "";
	let afterStarted = false;
	const afterEnd = afterStart + afterLen;

	// Track styling state so "after" inherits styling from before the overlay
	pooledStyleTracker.clear();

	while (i < line.length) {
		const ansiEnd = findTerminalSequenceEnd(line, i);
		if (ansiEnd !== 0) {
			const code = line.substring(i, ansiEnd);
			// Track all SGR codes to know styling state at afterStart
			pooledStyleTracker.process(code);
			// Include ANSI codes in their respective segments
			if (currentCol < beforeEnd) {
				pendingAnsiBefore += code;
			} else if (
				currentCol >= afterStart && currentCol < afterEnd && (afterStarted || code.startsWith("\x1b_"))
			) {
				// SGR is restored by the style tracker; zero-width APC cursor markers are not.
				after += code;
			}
			i = ansiEnd;
			continue;
		}

		let textEnd = i;
		while (textEnd < line.length && findTerminalSequenceEnd(line, textEnd) === 0) textEnd++;

		if (isSimpleTerminalAsciiRun(line, i, textEnd)) {
			for (let textIndex = i; textIndex < textEnd; textIndex++) {
				const width = line.charCodeAt(textIndex) === 0x09 ? 3 : 1;
				if (currentCol < beforeEnd && currentCol + width <= beforeEnd) {
					if (pendingAnsiBefore) {
						before += pendingAnsiBefore;
						pendingAnsiBefore = "";
					}
					before += line[textIndex];
					beforeWidth += width;
				} else if (currentCol >= afterStart && currentCol < afterEnd) {
					const fits = !strictAfter || currentCol + width <= afterEnd;
					if (fits) {
						if (!afterStarted) {
							after += pooledStyleTracker.getActiveCodes();
							afterStarted = true;
						}
						after += line[textIndex];
						afterWidth += width;
					}
				}
				currentCol += width;
				if (afterLen <= 0 ? currentCol >= beforeEnd : currentCol >= afterEnd) break;
			}
		} else {
			for (const part of graphemeSegmenter.segment(line.substring(i, textEnd))) {
				const segment = part.segment;
				const width = graphemeWidth(segment);
				if (currentCol < beforeEnd && currentCol + width <= beforeEnd) {
					if (pendingAnsiBefore) {
						before += pendingAnsiBefore;
						pendingAnsiBefore = "";
					}
					before += segment;
					beforeWidth += width;
				} else if (currentCol >= afterStart && currentCol < afterEnd) {
					const fits = !strictAfter || currentCol + width <= afterEnd;
					if (fits) {
						if (!afterStarted) {
							after += pooledStyleTracker.getActiveCodes();
							afterStarted = true;
						}
						after += segment;
						afterWidth += width;
					}
				}
				currentCol += width;
				if (afterLen <= 0 ? currentCol >= beforeEnd : currentCol >= afterEnd) break;
			}
		}
		i = textEnd;
		if (afterLen <= 0 ? currentCol >= beforeEnd : currentCol >= afterEnd) break;
	}

	result.before = before;
	result.beforeWidth = beforeWidth;
	result.after = after;
	result.afterWidth = afterWidth;
}

/**
 * Apply terminal reverse-video to one visible-column range in one line scan.
 * The output is a new immutable line string; no range or segment wrapper is created.
 */
export function highlightTerminalColumns(line: string, startColumn: number, endColumn: number, lineWidth: number): string {
	// APC markers are positional; do not replay them as inherited styles in later segments.
	let before = "";
	let selected = "\x1b[7m";
	let after = "";
	let pendingSelected = "";
	let pendingAfter = "";
	let currentColumn = 0;
	let index = 0;
	while (index < line.length) {
		const ansiEnd = findTerminalSequenceEnd(line, index);
		if (ansiEnd !== 0) {
			const code = line.substring(index, ansiEnd);
			if (currentColumn < startColumn) before += code;
			if (currentColumn >= startColumn && currentColumn < endColumn) {
				if (pendingSelected) {
					selected += pendingSelected;
					pendingSelected = "";
				}
				selected += code;
				if (code.endsWith("m")) selected += "\x1b[7m";
			} else if (currentColumn < startColumn && !code.startsWith("\x1b_")) {
				pendingSelected += code;
				if (code.endsWith("m")) pendingSelected += "\x1b[7m";
			}
			if (currentColumn >= endColumn && currentColumn < lineWidth) {
				if (pendingAfter) {
					after += pendingAfter;
					pendingAfter = "";
				}
				after += code;
			} else if (currentColumn < endColumn && !code.startsWith("\x1b_")) pendingAfter += code;
			index = ansiEnd;
			continue;
		}

		let textEnd = index;
		while (textEnd < line.length && findTerminalSequenceEnd(line, textEnd) === 0) textEnd++;
		if (isSimpleTerminalAsciiRun(line, index, textEnd)) {
			for (let textIndex = index; textIndex < textEnd; textIndex++) {
				const width = line.charCodeAt(textIndex) === 0x09 ? 3 : 1;
				if (currentColumn < startColumn && currentColumn + width <= startColumn) before += line[textIndex];
				else if (currentColumn >= startColumn && currentColumn < endColumn && currentColumn + width <= endColumn) {
					if (pendingSelected.length !== 0) {
						selected += pendingSelected;
						pendingSelected = "";
					}
					selected += line[textIndex];
				} else if (currentColumn >= endColumn && currentColumn < lineWidth && currentColumn + width <= lineWidth) {
					if (pendingAfter.length !== 0) {
						after += pendingAfter;
						pendingAfter = "";
					}
					after += line[textIndex];
				}
				currentColumn += width;
				if (currentColumn >= lineWidth) break;
			}
		} else {
			for (const part of graphemeSegmenter.segment(line.substring(index, textEnd))) {
				const segment = part.segment;
				const width = graphemeWidth(segment);
				if (currentColumn < startColumn && currentColumn + width <= startColumn) before += segment;
				else if (currentColumn >= startColumn && currentColumn < endColumn && currentColumn + width <= endColumn) {
					if (pendingSelected.length !== 0) {
						selected += pendingSelected;
						pendingSelected = "";
					}
					selected += segment;
				} else if (currentColumn >= endColumn && currentColumn < lineWidth && currentColumn + width <= lineWidth) {
					if (pendingAfter.length !== 0) {
						after += pendingAfter;
						pendingAfter = "";
					}
					after += segment;
				}
				currentColumn += width;
				if (currentColumn >= lineWidth) break;
			}
		}
		index = textEnd;
		if (currentColumn >= lineWidth) break;
	}
	return before + selected + "\x1b[27m" + after;
}
